from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    od = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'get':
            if key in od:
                value, wt = od[key]
                if t >= wt + ttl:
                    # expired
                    del od[key]
                    results.append(-1)
                else:
                    od.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

        elif kind == 'put':
            value = op[3]
            if key in od:
                old_value, wt = od[key]
                if t >= wt + ttl:
                    # expired, treat as absent -> remove then insert fresh
                    del od[key]
                    if len(od) >= capacity:
                        od.popitem(last=False)
                    od[key] = (value, t)
                    od.move_to_end(key)
                else:
                    # present, update value/time, move to most recently used
                    od[key] = (value, t)
                    od.move_to_end(key)
            else:
                if len(od) >= capacity:
                    od.popitem(last=False)
                od[key] = (value, t)
                od.move_to_end(key)

    return results

